package block

import (
	"image/color"

	"github.com/df-mc/dragonfly/server/block/cube"
	"github.com/df-mc/dragonfly/server/block/model"
	"github.com/df-mc/dragonfly/server/item"
	"github.com/df-mc/dragonfly/server/world"
	"github.com/go-gl/mathgl/mgl64"
)

type shellBuildingBlock struct{ State uint16 }

type shellBlockModelKind uint8

const (
	shellModelSolid shellBlockModelKind = iota
	shellModelEmpty
	shellModelCarpet
)

type shellBlockState struct {
	Name       string
	Properties map[string]any
	Model      shellBlockModelKind
	Item       bool
}

var shellBuildingBlockHash = NextHash()

// registeredShellBlockStates tracks which shellBlockStates indices were
// actually registered as shellBuildingBlock blocks (i.e. states that didn't
// already have a concrete block implementation). Populated by
// registerShellBuildingBlocks and consulted by registerShellBuildingItems so
// we don't register a shell-as-item for a state whose block side is owned by
// a concrete (non-shell) block — registering one anyway would crash
// BlockRuntimeID at runtime when creative content (or any consumer) tries to
// resolve the shell's hash, since shellBuildingBlock{State:i} isn't in the
// hash map for that i.
var registeredShellBlockStates = map[uint16]struct{}{}

func (s shellBuildingBlock) shellState() shellBlockState { return shellBlockStates[int(s.State)] }

func (s shellBuildingBlock) Hash() (uint64, uint64) { return shellBuildingBlockHash, uint64(s.State) }

func (s shellBuildingBlock) Model() world.BlockModel {
	switch s.shellState().Model {
	case shellModelEmpty:
		return model.Empty{}
	case shellModelCarpet:
		return model.Carpet{}
	default:
		return model.Solid{}
	}
}

func (s shellBuildingBlock) BreakInfo() BreakInfo {
	return newBreakInfo(0.5, alwaysHarvestable, nothingEffective, oneOf(s))
}

func (s shellBuildingBlock) EncodeItem() (string, int16) { return s.shellState().Name, 0 }

func (s shellBuildingBlock) EncodeBlock() (string, map[string]any) {
	st := s.shellState()
	return st.Name, st.Properties
}

func (s shellBuildingBlock) UseOnBlock(pos cube.Pos, face cube.Face, _ mgl64.Vec3, tx *world.Tx, user item.User, ctx *item.UseContext) bool {
	pos, _, used := firstReplaceable(tx, pos, face, s)
	if !used {
		return false
	}
	place(tx, pos, s, user, ctx)
	return placed(ctx)
}

func (s shellBuildingBlock) LightDiffusionLevel() uint8 {
	if s.shellState().Model == shellModelSolid {
		return 15
	}
	return 0
}

func (s shellBuildingBlock) SideClosed(cube.Pos, cube.Pos, *world.Tx) bool { return false }

func (s shellBuildingBlock) Color() color.RGBA { return color.RGBA{127, 127, 127, 255} }

func registerShellBuildingBlocks() {
	for i := range shellBlockStates {
		st := shellBlockStates[i]
		if world.BlockImplemented(st.Name, st.Properties) {
			continue
		}
		world.RegisterBlock(shellBuildingBlock{State: uint16(i)})
		registeredShellBlockStates[uint16(i)] = struct{}{}
	}
}

func registerShellBuildingItems() {
	registered := map[string]struct{}{}
	for i, st := range shellBlockStates {
		if !st.Item {
			continue
		}
		if _, ok := registered[st.Name]; ok {
			continue
		}
		// Skip when the block side at this state is owned by a concrete
		// (non-shell) block. Registering shellBuildingBlock{State:i} as
		// the item form would later crash BlockRuntimeID(shell) — the
		// shell is not in the hash map for state i.
		if _, isShell := registeredShellBlockStates[uint16(i)]; !isShell {
			continue
		}
		registered[st.Name] = struct{}{}
		if _, ok := world.ItemByName(st.Name, 0); ok {
			continue
		}
		world.RegisterItem(shellBuildingBlock{State: uint16(i)})
	}
}

// ShellBuildingCreativeItems returns one item form for every shell-only
// building block that should be exposed in the creative inventory.
func ShellBuildingCreativeItems() []world.Item {
	items := make([]world.Item, 0, len(shellBlockStates))
	registered := map[string]struct{}{}
	for _, st := range shellBlockStates {
		if !st.Item {
			continue
		}
		if _, ok := registered[st.Name]; ok {
			continue
		}
		b, ok := world.BlockByName(st.Name, st.Properties)
		if !ok {
			continue
		}
		if _, ok := b.(shellBuildingBlock); !ok {
			continue
		}
		it, ok := b.(world.Item)
		if !ok {
			continue
		}
		registered[st.Name] = struct{}{}
		items = append(items, it)
	}
	return items
}

